(async()=>{const out={};for(const rate of [.1,1.1]){const c=new OfflineAudioContext(1,384,8000),s=c.createBufferSource(),b=c.createBuffer(1,4,8000);b.getChannelData(0).set([0,1,0,-1]);s.buffer=b;s.loop=true;s.playbackRate.value=rate;s.connect(c.destination);s.start();out[rate]=Array.from((await c.startRendering()).getChannelData(0))}const c=new OfflineAudioContext(1,384,48000),s=c.createBufferSource(),b=c.createBuffer(1,4,44100);b.getChannelData(0).set([0,1,0,-1]);s.buffer=b;s.loop=true;s.connect(c.destination);s.start();out['44100/48000']=Array.from((await c.startRendering()).getChannelData(0));for(const rate of [.1,1.1]){const c=new OfflineAudioContext(1,384,48000),s=c.createBufferSource(),b=c.createBuffer(1,4,44100);b.getChannelData(0).set([0,1,0,-1]);s.buffer=b;s.loop=true;s.playbackRate.value=rate;s.connect(c.destination);s.start();out['44100/48000:'+rate]=Array.from((await c.startRendering()).getChannelData(0))}return out})()
